const msg = $input.first().json.message;
return [{
  json: {
    chat_id: msg.chat.id,
    telegram_user: msg.chat.id.toString(),
    text: (msg.text || '').trim(),
    nombre_telegram: msg.chat.first_name || ''
  }
}];

const base = $('Sesion Nueva').item.json;
const fila = $input.first().json;
return [{ json: { ...base, row_number: fila.row_number } }];

const idEstudiante = $('Buscar Estudiante (consulta)').item.json.id_estudiante;
const filas = $input.all().map(i => i.json).filter(f => String(f.id_estudiante) === String(idEstudiante));
let mensaje = 'No tienes tutorias registradas todavia.';
if (filas.length > 0) {
  const lista = filas.map(f => `${f.materia} - ${f.fecha} ${f.hora} (${f.estado})`).join('\n');
  mensaje = 'Tus tutorias:\n' + lista;
}
return [{ json: {
  chat_id: $('Extraer Datos Mensaje').item.json.chat_id,
  mensaje
} }];
